import { useEffect } from "react";

export default function Hero() {

useEffect(() => {
 var TxtRotate = function (el, toRotate, period) {
  this.toRotate = toRotate;
  this.el = el;
  this.loopNum = 0;
  this.period = parseInt(period, 10) || 2000;
  this.txt = "";
  this.tick();
  this.isDeleting = false;
};

TxtRotate.prototype.tick = function () {
  var i = this.loopNum % this.toRotate.length;
  var fullTxt = this.toRotate[i];

  if (this.isDeleting) {
    this.txt = fullTxt.substring(0, this.txt.length - 1);
  } else {
    this.txt = fullTxt.substring(0, this.txt.length + 1);
  }

  this.el.innerHTML = '<span class="wrap">' + this.txt + "</span>";

  var that = this;
  var delta = 300 - Math.random() * 100;

  if (this.isDeleting) {
    delta /= 2;
  }

  if (!this.isDeleting && this.txt === fullTxt) {
    delta = this.period;
    this.isDeleting = true;
  } else if (this.isDeleting && this.txt === "") {
    this.isDeleting = false;
    this.loopNum++;
    delta = 500;
  }

  setTimeout(function () {
    that.tick();
  }, delta);
};

window.onload = function () {
  var elements = document.getElementsByClassName("txt-rotate");
  for (var i = 0; i < elements.length; i++) {
    var toRotate = elements[i].getAttribute("data-rotate");
    var period = elements[i].getAttribute("data-period");
    if (toRotate) {
      new TxtRotate(elements[i], JSON.parse(toRotate), period);
    }
  }
  // INJECT CSS
  var css = document.createElement("style");
  css.type = "text/css";
  css.innerHTML = ".txt-rotate > .wrap { border-right: 0.08em solid #feb81d }";
  document.body.appendChild(css);
};


}, []);




  return (
    <section id="home-slider" >
  <div className="slider-wrap">

    <div className="text">
      <h1>
        Your <b>Trusted</b> Link Building Partner <br />
        for <span className="txt-rotate" data-period="2000" data-rotate='[ "Small", "Medium", "Enterprises" ]'></span> Digital Agencies
      </h1>

      <p>
        Providing essential services for improving search engine rankings through effective link building.
        helping businesses grow their online visibility.
      </p>

      <div className="buttons">
        <div className="default_btn">
          <a href="https://app.grolinq.com">Grow Your Agency Now</a>
        </div>
      </div>
    </div>

  </div>
</section>



  );
}
